SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
ALTER TABLE pharmacy_supplier_receiving_closures ADD COLUMN summary_version bigint CHECK(summary_version BETWEEN 1 AND 9007199254740991);
ALTER TABLE pharmacy_supplier_receiving_closures DROP CONSTRAINT pharmacy_supplier_receiving_closures_tenant_id_shipment_id_key;
ALTER TABLE pharmacy_supplier_receiving_closures ADD UNIQUE(tenant_id,shipment_id,summary_version);
CREATE TABLE pharmacy_supplier_receiving_corrections(
 tenant_id uuid NOT NULL,id uuid NOT NULL,shipment_id uuid NOT NULL,receipt_id uuid NOT NULL,outlet_id uuid NOT NULL,version bigint NOT NULL CHECK(version BETWEEN 2 AND 1000),input jsonb NOT NULL,accepted_delta_units bigint NOT NULL CHECK(accepted_delta_units BETWEEN -1000000000 AND 1000000000),body jsonb NOT NULL,actor_subject text NOT NULL,actor_staff_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,receipt_id,version),FOREIGN KEY(tenant_id,receipt_id)REFERENCES pharmacy_supplier_receipts(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,shipment_id)REFERENCES pharmacy_supplier_receiving_heads(tenant_id,shipment_id)ON DELETE RESTRICT,
 CHECK(body->>'id'IS NOT DISTINCT FROM id::text AND body->>'owner_tenant_id'IS NOT DISTINCT FROM tenant_id::text AND body->>'shipment_id'IS NOT DISTINCT FROM shipment_id::text AND body->>'receipt_id'IS NOT DISTINCT FROM receipt_id::text AND body->>'outlet_id'IS NOT DISTINCT FROM outlet_id::text AND body->>'version'IS NOT DISTINCT FROM version::text AND body->'input'=input AND body->>'accepted_delta_units'IS NOT DISTINCT FROM accepted_delta_units::text AND body->>'actor_subject'IS NOT DISTINCT FROM actor_subject AND body->>'actor_staff_id'IS NOT DISTINCT FROM actor_staff_id::text),
 CHECK((input->>'counted_units')::bigint BETWEEN 0 AND 1000000000 AND(input->>'accepted_units')::bigint BETWEEN 0 AND(input->>'counted_units')::bigint AND(input->>'rejected_units')::bigint BETWEEN 0 AND(input->>'counted_units')::bigint AND(input->>'accepted_units')::bigint+(input->>'rejected_units')::bigint=(input->>'counted_units')::bigint AND length(input->>'reason')BETWEEN 1 AND 500),
 CHECK((accepted_delta_units=0 AND body->>'movement_id'IS NULL)OR(accepted_delta_units<>0 AND body->>'movement_id'=id::text))
);
ALTER TABLE pharmacy_supplier_receiving_corrections ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_receiving_corrections FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_receiving_corrections USING(hms_tenant_visible(tenant_id)AND pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false))WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid AND pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND current_setting('app.pharmacy_receiving_purpose',true)='review'AND actor_subject=current_setting('app.actor_subject',true)AND actor_staff_id=NULLIF(current_setting('app.pharmacy_receiving_staff',true),'')::uuid);
CREATE INDEX ON pharmacy_supplier_receiving_corrections(tenant_id,shipment_id,receipt_id,version DESC);
CREATE INDEX ON pharmacy_supplier_receipts(tenant_id,outlet_id,destination_batch_id);
CREATE FUNCTION pharmacy_supplier_correction_guard()RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r pharmacy_supplier_receipts;p pharmacy_supplier_receiving_corrections;h pharmacy_supplier_receiving_heads;old_count bigint;old_accept bigint;old_reject bigint;previous_version bigint;previous_actor uuid;status text;physical bigint;expected bigint;
BEGIN
 SELECT *INTO STRICT r FROM pharmacy_supplier_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id AND shipment_id=NEW.shipment_id AND outlet_id=NEW.outlet_id;
 SELECT *INTO STRICT h FROM pharmacy_supplier_receiving_heads WHERE tenant_id=NEW.tenant_id AND shipment_id=NEW.shipment_id;
 SELECT *INTO p FROM pharmacy_supplier_receiving_corrections WHERE tenant_id=NEW.tenant_id AND receipt_id=NEW.receipt_id ORDER BY version DESC LIMIT 1;
 previous_version:=COALESCE(p.version,1);previous_actor:=COALESCE(p.actor_staff_id,r.actor_staff_id);
 old_count:=COALESCE((p.input->>'counted_units')::bigint,r.counted_units);old_accept:=COALESCE((p.input->>'accepted_units')::bigint,r.accepted_units);old_reject:=COALESCE((p.input->>'rejected_units')::bigint,r.rejected_units);
 IF h.summary->>'id'IS DISTINCT FROM NEW.id::text OR NEW.created_at<r.created_at OR NEW.created_at<COALESCE(p.created_at,r.created_at) OR NEW.version<>previous_version+1 OR NEW.actor_staff_id IN(r.actor_staff_id,previous_actor)OR(NEW.input->>'expected_receipt_version')::bigint<>previous_version OR(NEW.input->>'expected_summary_version')::bigint<>h.version-1 OR h.closed OR NEW.accepted_delta_units<>(NEW.input->>'accepted_units')::bigint-old_accept OR NEW.body->>'cumulative_counted_units'IS DISTINCT FROM h.counted_units::text OR NEW.body->>'cumulative_accepted_units'IS DISTINCT FROM h.accepted_units::text OR NEW.body->>'cumulative_rejected_units'IS DISTINCT FROM h.rejected_units::text OR(NEW.input->>'counted_units')::bigint=old_count AND(NEW.input->>'accepted_units')::bigint=old_accept AND(NEW.input->>'rejected_units')::bigint=old_reject THEN RAISE EXCEPTION 'stale or self-reviewed receiving correction' USING ERRCODE='23514';END IF;
 IF NEW.accepted_delta_units>0 THEN
  IF COALESCE((NEW.input->>'identity_confirmed')::boolean,false)=false THEN RAISE EXCEPTION 'increased acceptance requires current identity confirmation' USING ERRCODE='23514';END IF;
  PERFORM b.id FROM pharmacy_stock_batches b JOIN pharmacy_catalogue_products product ON product.tenant_id=b.tenant_id AND product.outlet_id=b.outlet_id AND product.id=b.product_id WHERE b.tenant_id=NEW.tenant_id AND b.outlet_id=NEW.outlet_id AND b.id=r.destination_batch_id AND b.product_id::text=r.body#>>'{input,destination_product_id}'AND b.product_version=(r.body#>>'{input,destination_product_version}')::bigint AND product.version=b.product_version AND product.status='active'AND product.unit_of_issue=h.shipment->>'unit_code'AND product.pack_size=(h.shipment->>'pack_size')::bigint AND b.lot_number=r.body#>>'{input,observed_lot_number}'AND b.expires_on=(r.body#>>'{input,observed_expires_on}')::date AND b.expires_on>(clock_timestamp()AT TIME ZONE 'Asia/Kolkata')::date AND b.mrp_minor=(r.body#>>'{input,mrp_minor}')::bigint FOR SHARE OF b,product;
  IF NOT FOUND THEN RAISE EXCEPTION 'receipt stock identity or expiry changed' USING ERRCODE='23514';END IF;
 END IF;
 IF NEW.accepted_delta_units<>0 THEN
  IF r.destination_batch_id IS NULL OR r.quarantine_location_id IS NULL THEN RAISE EXCEPTION 'correction has no original stock identity' USING ERRCODE='23514';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id::text||':'||NEW.outlet_id::text||':'||r.quarantine_location_id::text||':'||r.destination_batch_id::text,0));
  SELECT stock_status INTO STRICT status FROM pharmacy_stock_locations WHERE tenant_id=NEW.tenant_id AND outlet_id=NEW.outlet_id AND id=r.quarantine_location_id FOR SHARE;
  SELECT COALESCE(SUM(quantity_units),0)INTO physical FROM pharmacy_stock_movements WHERE tenant_id=NEW.tenant_id AND outlet_id=NEW.outlet_id AND batch_id=r.destination_batch_id AND location_id=r.quarantine_location_id;
  SELECT COALESCE(SUM(accepted_units),0)INTO expected FROM pharmacy_supplier_receipts WHERE tenant_id=NEW.tenant_id AND outlet_id=NEW.outlet_id AND destination_batch_id=r.destination_batch_id;
  SELECT expected+COALESCE(SUM(c.accepted_delta_units),0)INTO expected FROM pharmacy_supplier_receiving_corrections c JOIN pharmacy_supplier_receipts origin ON origin.tenant_id=c.tenant_id AND origin.id=c.receipt_id WHERE origin.tenant_id=NEW.tenant_id AND origin.outlet_id=NEW.outlet_id AND origin.destination_batch_id=r.destination_batch_id;
  IF status<>'quarantine'OR physical<>expected OR physical+NEW.accepted_delta_units<0 OR EXISTS(SELECT 1 FROM pharmacy_stock_movements WHERE tenant_id=NEW.tenant_id AND outlet_id=NEW.outlet_id AND batch_id=r.destination_batch_id AND(location_id<>r.quarantine_location_id OR kind NOT IN('receipt','correction')))THEN RAISE EXCEPTION 'supplier goods have left original quarantine custody' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER pharmacy_supplier_correction_guard BEFORE INSERT ON pharmacy_supplier_receiving_corrections FOR EACH ROW EXECUTE FUNCTION pharmacy_supplier_correction_guard();
CREATE TRIGGER pharmacy_supplier_correction_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON pharmacy_supplier_receiving_corrections FOR EACH STATEMENT EXECUTE FUNCTION pharmacy_supplier_evidence_immutable();
CREATE TRIGGER pharmacy_supplier_correction_audit AFTER INSERT ON pharmacy_supplier_receiving_corrections FOR EACH ROW EXECUTE FUNCTION audit_record_change();
DO $$DECLARE prior text;BEGIN
 SELECT pg_get_expr(polwithcheck,polrelid)INTO STRICT prior FROM pg_policy WHERE polrelid='pharmacy_stock_movements'::regclass AND polname='tenant_isolation';
 EXECUTE format($policy$ALTER POLICY tenant_isolation ON pharmacy_stock_movements WITH CHECK((%s)OR(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND current_setting('app.pharmacy_receiving_purpose',true)='review'AND kind='correction'AND actor_subject=current_setting('app.actor_subject',true)AND source_reference='supplier-correction:'||id::text AND EXISTS(SELECT 1 FROM pharmacy_supplier_receiving_corrections c JOIN pharmacy_supplier_receipts r ON r.tenant_id=c.tenant_id AND r.id=c.receipt_id WHERE c.tenant_id=pharmacy_stock_movements.tenant_id AND c.id=pharmacy_stock_movements.id AND c.outlet_id=pharmacy_stock_movements.outlet_id AND r.destination_batch_id=pharmacy_stock_movements.batch_id AND r.quarantine_location_id=pharmacy_stock_movements.location_id AND c.accepted_delta_units=pharmacy_stock_movements.quantity_units)))$policy$,prior);
END $$;
